DROP TABLE IF EXISTS `parking_account`;
CREATE TABLE `parking_account`  (
  `account_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '账户ID',
  `tenant_id` bigint(0) NOT NULL COMMENT '租户ID',
  `total_income_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '累计收入',
  `balance_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '账户余额',
  `available_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '可提现余额',
  `frozen_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '冻结金额',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '状态（0正常 1冻结）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`account_id`) USING BTREE,
  UNIQUE INDEX `uk_parking_account_tenant`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '租户账户表' ROW_FORMAT = DYNAMIC;

