-- ----------------------------
-- Table structure for parking_charge_rule
-- ----------------------------
DROP TABLE IF EXISTS `parking_charge_rule`;
CREATE TABLE `parking_charge_rule`  (
  `rule_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '规则ID',
  `tenant_id` bigint(0) NOT NULL COMMENT '租户ID',
  `default_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '是否默认规则（0否 1是）',
  `rule_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则名称',
  `free_minutes` int(0) NOT NULL DEFAULT 0 COMMENT '免费分钟数',
  `unit_minutes` int(0) NOT NULL DEFAULT 60 COMMENT '计费单位分钟',
  `unit_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '首个计费单位价格',
  `follow_unit_price` decimal(10, 2) NOT NULL DEFAULT 2.00 COMMENT '后续计费单位价格',
  `day_cap_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '24小时封顶金额',
  `pay_grace_minutes` int(0) NOT NULL DEFAULT 15 COMMENT '支付后离场宽限分钟',
  `overtime_recalc` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1' COMMENT '超时是否补费（0否 1是）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '状态（0启用 1停用）',
  `effective_time` datetime(0) NULL DEFAULT NULL COMMENT '生效时间',
  `expire_time` datetime(0) NULL DEFAULT NULL COMMENT '失效时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`rule_id`) USING BTREE,
  INDEX `idx_parking_rule_tenant`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '收费规则主表' ROW_FORMAT = DYNAMIC;

