DROP TABLE IF EXISTS `parking_daily_stat`;
CREATE TABLE `parking_daily_stat`  (
  `stat_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '统计ID',
  `tenant_id` bigint(0) NOT NULL COMMENT '租户ID',
  `lot_id` bigint(0) NOT NULL COMMENT '停车场ID',
  `stat_date` date NOT NULL COMMENT '统计日期',
  `entry_count` int(0) NOT NULL DEFAULT 0 COMMENT '进场次数',
  `exit_count` int(0) NOT NULL DEFAULT 0 COMMENT '出场次数',
  `in_park_count` int(0) NOT NULL DEFAULT 0 COMMENT '在场数量',
  `order_count` int(0) NOT NULL DEFAULT 0 COMMENT '订单数',
  `paid_order_count` int(0) NOT NULL DEFAULT 0 COMMENT '已支付订单数',
  `income_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '收入金额',
  `avg_order_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '平均每单',
  `turnover_rate` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '车位周转率',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`stat_id`) USING BTREE,
  UNIQUE INDEX `uk_daily_stat`(`tenant_id`, `lot_id`, `stat_date`) USING BTREE,
  INDEX `idx_daily_stat_date`(`stat_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '停车场日统计表' ROW_FORMAT = DYNAMIC;

