  `device_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备编码',
  `device_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备名称',
  `device_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备类型（camera/barrier/allinone）',
  `vendor_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'SIM' COMMENT '厂商编码',
  `connect_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'SIMULATED' COMMENT '连接模式',
  `device_secret` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备密钥',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '状态（0在线 1离线 2停用）',
  `last_heartbeat_time` datetime(0) NULL DEFAULT NULL COMMENT '最后心跳时间',
  `config_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '设备配置JSON',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`device_id`) USING BTREE,
  UNIQUE INDEX `uk_parking_device_code`(`device_code`) USING BTREE,
  INDEX `idx_parking_device_tenant`(`tenant_id`) USING BTREE,
  INDEX `idx_parking_device_lot`(`lot_id`) USING BTREE,
  INDEX `idx_parking_device_gate`(`gate_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '停车设备表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of parking_device
-- ----------------------------

-- ----------------------------
-- Table structure for parking_gate
-- ----------------------------
DROP TABLE IF EXISTS `parking_gate`;
CREATE TABLE `parking_gate`  (
  `gate_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '通道ID',
  `tenant_id` bigint(0) NOT NULL COMMENT '租户ID',
  `lot_id` bigint(0) NOT NULL COMMENT '停车场ID',
  `gate_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '通道编码',
  `gate_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '通道名称',
  `gate_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '通道类型（1入口 2出口）',
  `sort_num` int(0) NOT NULL DEFAULT 0 COMMENT '排序号',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '状态（0启用 1停用）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`gate_id`) USING BTREE,
  UNIQUE INDEX `uk_parking_gate_code`(`gate_code`) USING BTREE,
  INDEX `idx_parking_gate_tenant`(`tenant_id`) USING BTREE,
  INDEX `idx_parking_gate_lot`(`lot_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '停车场通道表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of parking_gate
-- ----------------------------

-- ----------------------------
-- Table structure for parking_gate_command
-- ----------------------------
DROP TABLE IF EXISTS `parking_gate_command`;
CREATE TABLE `parking_gate_command`  (
  `command_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '指令ID',
  `tenant_id` bigint(0) NOT NULL COMMENT '租户ID',
  `lot_id` bigint(0) NOT NULL COMMENT '停车场ID',
  `gate_id` bigint(0) NOT NULL COMMENT '通道ID',
  `device_id` bigint(0) NOT NULL COMMENT '设备ID',
  `session_id` bigint(0) NULL DEFAULT NULL COMMENT '停车会话ID',
  `order_id` bigint(0) NULL DEFAULT NULL COMMENT '关联订单ID',
  `command_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '指令编号',
  `command_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '指令类型（OPEN_GATE）',
  `command_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '指令状态（INIT/SENT/SUCCESS/FAIL）',
  `command_time` datetime(0) NOT NULL COMMENT '下发时间',
  `callback_time` datetime(0) NULL DEFAULT NULL COMMENT '回调时间',
  `callback_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '回调报文',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`command_id`) USING BTREE,
  UNIQUE INDEX `uk_gate_command_no`(`command_no`) USING BTREE,
  INDEX `idx_gate_command_tenant`(`tenant_id`) USING BTREE,
  INDEX `idx_gate_command_device`(`device_id`) USING BTREE,
  INDEX `idx_gate_command_session`(`session_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '开闸指令表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of parking_gate_command
-- ----------------------------

-- ----------------------------
-- Table structure for parking_io_event
-- ----------------------------
DROP TABLE IF EXISTS `parking_io_event`;
CREATE TABLE `parking_io_event`  (
  `event_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '事件ID',
  `tenant_id` bigint(0) NOT NULL COMMENT '租户ID',
  `lot_id` bigint(0) NOT NULL COMMENT '停车场ID',
  `gate_id` bigint(0) NULL DEFAULT NULL COMMENT '通道ID',
  `device_id` bigint(0) NULL DEFAULT NULL COMMENT '设备ID',
  `event_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '事件编号',
  `event_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '事件类型（ENTRY/EXIT/HEARTBEAT/OPEN_RESULT）',
  `plate_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车牌号码',
  `event_time` datetime(0) NOT NULL COMMENT '事件时间',
  `image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图片地址',
  `raw_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原始报文',
  `handle_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'INIT' COMMENT '处理状态',
  `handle_msg` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '处理结果',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`event_id`) USING BTREE,
  UNIQUE INDEX `uk_io_event_no`(`event_no`) USING BTREE,
  INDEX `idx_io_event_tenant`(`tenant_id`) USING BTREE,
  INDEX `idx_io_event_lot`(`lot_id`) USING BTREE,
  INDEX `idx_io_event_device`(`device_id`) USING BTREE,
  INDEX `idx_io_event_plate`(`plate_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19344 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备事件表' ROW_FORMAT = DYNAMIC;

