-- Records of parking_lot
-- ----------------------------

-- ----------------------------
-- Table structure for parking_order
-- ----------------------------
DROP TABLE IF EXISTS `parking_order`;
CREATE TABLE `parking_order`  (
  `order_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `tenant_id` bigint(0) NOT NULL COMMENT '租户ID',
  `lot_id` bigint(0) NOT NULL COMMENT '停车场ID',
  `session_id` bigint(0) NOT NULL COMMENT '停车会话ID',
  `parent_order_id` bigint(0) NULL DEFAULT NULL COMMENT '父订单ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `order_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单类型（NORMAL/OVERTIME）',
  `plate_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '车牌号码',
  `entry_time` datetime(0) NOT NULL COMMENT '入场时间',
  `calc_time` datetime(0) NOT NULL COMMENT '计费时间',
  `parking_minutes` int(0) NOT NULL DEFAULT 0 COMMENT '计费停车时长',
  `payable_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '应付金额',
  `discount_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '优惠金额',
  `paid_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '实付金额',
  `order_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单状态',
  `pay_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '支付状态',
  `pay_time` datetime(0) NULL DEFAULT NULL COMMENT '支付时间',
  `leave_deadline_time` datetime(0) NULL DEFAULT NULL COMMENT '支付后离场截止时间',
  `close_time` datetime(0) NULL DEFAULT NULL COMMENT '关闭时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`order_id`) USING BTREE,
  UNIQUE INDEX `uk_parking_order_no`(`order_no`) USING BTREE,
  INDEX `idx_order_tenant`(`tenant_id`) USING BTREE,
  INDEX `idx_order_lot`(`lot_id`) USING BTREE,
  INDEX `idx_order_session`(`session_id`) USING BTREE,
  INDEX `idx_order_plate`(`plate_no`) USING BTREE,
  INDEX `idx_order_status`(`order_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '停车订单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of parking_order
-- ----------------------------

-- ----------------------------
-- Table structure for parking_payment
-- ----------------------------
DROP TABLE IF EXISTS `parking_payment`;
CREATE TABLE `parking_payment`  (
  `payment_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '支付流水ID',
  `tenant_id` bigint(0) NOT NULL COMMENT '租户ID',
  `lot_id` bigint(0) NOT NULL COMMENT '停车场ID',
  `order_id` bigint(0) NOT NULL COMMENT '订单ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `payment_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '支付流水号',
  `pay_channel` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '支付渠道',
  `pay_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '支付金额',
  `pay_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '支付状态',
  `third_trade_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '第三方交易号',
  `notify_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '回调报文',
  `pay_success_time` datetime(0) NULL DEFAULT NULL COMMENT '支付成功时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`payment_id`) USING BTREE,
  UNIQUE INDEX `uk_parking_payment_no`(`payment_no`) USING BTREE,
  INDEX `idx_payment_order`(`order_id`) USING BTREE,
  INDEX `idx_payment_tenant`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '支付流水表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of parking_payment
-- ----------------------------

-- ----------------------------
-- Table structure for parking_session
-- ----------------------------
DROP TABLE IF EXISTS `parking_session`;
CREATE TABLE `parking_session`  (
  `session_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '停车会话ID',
  `tenant_id` bigint(0) NOT NULL COMMENT '租户ID',
  `lot_id` bigint(0) NOT NULL COMMENT '停车场ID',
  `plate_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '车牌号码',
  `plate_color` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车牌颜色',
  `car_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车辆类型',
  `entry_gate_id` bigint(0) NULL DEFAULT NULL COMMENT '入口通道ID',
  `entry_device_id` bigint(0) NULL DEFAULT NULL COMMENT '入口设备ID',
  `entry_time` datetime(0) NOT NULL COMMENT '入场时间',
  `entry_image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入场抓拍图',
  `exit_gate_id` bigint(0) NULL DEFAULT NULL COMMENT '出口通道ID',
  `exit_device_id` bigint(0) NULL DEFAULT NULL COMMENT '出口设备ID',
  `exit_time` datetime(0) NULL DEFAULT NULL COMMENT '出场时间',
  `exit_image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '出场抓拍图',
  `parking_minutes` int(0) NULL DEFAULT NULL COMMENT '停车时长（分钟）',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会话状态',
  `current_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当前待处理订单号',
  `total_payable_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '累计应收金额',
  `total_paid_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '累计实收金额',
  `leave_deadline_time` datetime(0) NULL DEFAULT NULL COMMENT '支付后离场截止时间',
  `is_abnormal` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '是否异常（0否 1是）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`session_id`) USING BTREE,
  INDEX `idx_session_tenant`(`tenant_id`) USING BTREE,
  INDEX `idx_session_lot`(`lot_id`) USING BTREE,
  INDEX `idx_session_plate`(`plate_no`) USING BTREE,
  INDEX `idx_session_status`(`status`) USING BTREE,
  INDEX `idx_session_entry_time`(`entry_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '停车会话主表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of parking_session
-- ----------------------------

-- ----------------------------
-- Table structure for parking_simulator_device
-- ----------------------------
DROP TABLE IF EXISTS `parking_simulator_device`;
CREATE TABLE `parking_simulator_device`  (
  `sim_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `device_id` bigint(0) NOT NULL COMMENT '停车设备ID',
  `simulator_enabled` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '是否启用模拟器 1是0否',
  `simulator_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'STOPPED' COMMENT '模拟器状态 RUNNING/STOPPED',
  `online_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'OFFLINE' COMMENT '在线状态 ONLINE/OFFLINE',
  `auto_heartbeat` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '1' COMMENT '是否自动心跳 1是0否',
  `heartbeat_interval_sec` int(0) NOT NULL DEFAULT 30 COMMENT '心跳间隔秒数',
  `auto_callback` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '1' COMMENT '是否自动回调开闸结果 1是0否',
  `callback_delay_sec` int(0) NOT NULL DEFAULT 1 COMMENT '自动回调延迟秒数',
  `last_heartbeat_time` datetime(0) NULL DEFAULT NULL COMMENT '最近一次心跳时间',
  `last_request_time` datetime(0) NULL DEFAULT NULL COMMENT '最近一次请求时间',
  `last_response_code` int(0) NULL DEFAULT NULL COMMENT '最近一次平台返回码',
  `last_response_msg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '最近一次平台返回消息',
  `last_command_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '最近一次指令号',
  `last_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '最近一次订单号',
  `default_plate_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '粤B12345' COMMENT '默认模拟车牌号',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`sim_id`) USING BTREE,
  UNIQUE INDEX `uk_device_id`(`device_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '停车设备模拟器状态表' ROW_FORMAT = DYNAMIC;

