-- ----------------------------
-- Table structure for parking_withdraw_order
-- ----------------------------
DROP TABLE IF EXISTS `parking_withdraw_order`;
CREATE TABLE `parking_withdraw_order`  (
  `withdraw_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '提现单ID',
  `tenant_id` bigint(0) NOT NULL COMMENT '租户ID',
  `withdraw_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '提现单号',
  `apply_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '申请金额',
  `fee_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '手续费',
  `real_amount` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '实到账金额',
  `fee_rate` decimal(5, 4) NOT NULL DEFAULT 0.0060 COMMENT '手续费率',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '状态',
  `audit_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `audit_time` datetime(0) NULL DEFAULT NULL COMMENT '审核时间',
  `audit_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `pay_time` datetime(0) NULL DEFAULT NULL COMMENT '打款时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`withdraw_id`) USING BTREE,
  UNIQUE INDEX `uk_withdraw_no`(`withdraw_no`) USING BTREE,
  INDEX `idx_withdraw_tenant`(`tenant_id`) USING BTREE,
  INDEX `idx_withdraw_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '提现申请单' ROW_FORMAT = DYNAMIC;

